mkdir -p tests && cat > tests/verify_data.mjs <<'EOF'
// Integrity and sanity checks on the generated data in public/data.
// usage: npm test
import fs from 'node:fs';
import zlib from 'node:zlib';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const dir = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', 'public', 'data');
let failed = 0, passed = 0;
const ok = (cond, msg) => { if (cond) passed++; else { failed++; console.error('  FAIL', msg); } };
const gz = (name) => { const b = zlib.gunzipSync(fs.readFileSync(path.join(dir, name))); return b.buffer.slice(b.byteOffset, b.byteOffset + b.byteLength); };

const meta = JSON.parse(fs.readFileSync(path.join(dir, 'meta.json'), 'utf8'));
const stations = JSON.parse(fs.readFileSync(path.join(dir, 'stations.json'), 'utf8'));
const { w, h, sW, sH } = meta.grid, NL = meta.nl;
console.log(`grid ${w}x${h} @ ${meta.grid.cell} m, ${meta.counts.buildings} buildings, ${stations.length} stations`);

// ---- raster sizes
const T = new Int16Array(gz('flood_T.bin.gz')), G = new Uint16Array(gz('ground.bin.gz'));
const masks = new Uint8Array(gz('masks.bin.gz')), pa = new Uint8Array(gz('ppri_a.bin.gz')), pb = new Uint8Array(gz('ppri_b.bin.gz'));
ok(T.length === w * h, 'flood_T size'); ok(G.length === w * h, 'ground size'); ok(masks.length === w * h * 4, 'masks size');
ok(pa.length === w * h * 4, 'ppri_a size'); ok(pb.length === w * h * 2, 'ppri_b size');
ok(new Float32Array(gz('river_s.bin.gz')).length === sW * sH, 'river_s size');

// ---- ground model range (NGF)
let gmin = 1e9, gmax = -1e9;
for (let i = 0; i < G.length; i++) { const v = G[i] / 100 + meta.grid.groundBase; if (masks[i * 4 + 3] > 128) { gmin = Math.min(gmin, v); gmax = Math.max(gmax, v); } }
console.log(`ground inside Paris: ${gmin.toFixed(1)} .. ${gmax.toFixed(1)} m NGF`);
ok(gmin > 20 && gmin < 30, 'lowest ground near the Seine'); ok(gmax > 120 && gmax < 135, 'highest ground ~ Butte Montmartre/Belleville (128 m)');

// ---- buildings
const geom = gz('buildings_geom.bin.gz'), hd = new Int32Array(geom, 0, 8);
const n = hd[1], nRings = hd[2], nVerts = hd[3], nChunks = hd[4];
ok(hd[0] === 0x42444c47, 'geometry magic'); ok(n === meta.counts.buildings, 'building count matches meta');
const cb = new Int32Array(geom.slice(32, 32 + 4 * (nChunks + 1)));
ok(cb[0] === 0 && cb[nChunks] === n, 'chunk bounds cover all buildings');
let mono = true; for (let i = 1; i < cb.length; i++) if (cb[i] < cb[i - 1]) mono = false; ok(mono, 'chunk bounds monotonic');
let off = 32 + 4 * (nChunks + 1);
const ringCount = new Uint8Array(geom.slice(off, off + n)); off += n;
const ringLen = new Uint16Array(geom.slice(off, off + 2 * nRings)); off += 2 * nRings;
ok(ringCount.reduce((a, b) => a + b, 0) === nRings, 'ring counts sum'); ok(ringLen.reduce((a, b) => a + b, 0) === nVerts, 'vertex counts sum');
ok(ringLen.every((l) => l >= 3), 'every ring has >= 3 vertices');
off += 8 * n + 4 * nVerts; ok(off === geom.byteLength, 'geometry blob fully consumed');
const at = gz('buildings_attr.bin.gz'); ok(at.byteLength === n * (4 + 4 + 2 + 2 + 4 + 1 + 1 + 2), 'attribute blob size');
const z = new Float32Array(at, 0, n), hh = new Float32Array(at, 4 * n, n);
let zmin = 1e9, zmax = -1e9, hmax = 0, hmin = 1e9;
for (let i = 0; i < n; i++) { zmin = Math.min(zmin, z[i]); zmax = Math.max(zmax, z[i]); hmax = Math.max(hmax, hh[i]); hmin = Math.min(hmin, hh[i]); }
console.log(`building ground ${zmin.toFixed(1)}..${zmax.toFixed(1)} m, height ${hmin.toFixed(1)}..${hmax.toFixed(0)} m`);
ok(zmin > 20 && zmax < 135 && hmin >= 2.5 && hmax < 250, 'building ground / height ranges');
const arr = new Uint8Array(at, 16 * n + 4 * n - 4 * n + 0, 0); // placeholder to keep offsets explicit below
const arrOff = 4 * n * 3 + 2 * n * 2; // z,h,s (3x f32) + tc,tl (2x i16)
const arrB = new Uint8Array(at, arrOff, n); const counts = new Array(21).fill(0); for (const a of arrB) counts[a]++;
ok(counts[0] === 0 && counts.slice(1).every((c) => c > 1000), 'every arrondissement has buildings');

// ---- statistics
const st = gz('stats.bin.gz');
const bld = new Uint32Array(st, 0, 2 * 21 * NL), area = new Float32Array(st, 2 * 21 * NL * 4, 2 * 3 * NL);
const areaArr = new Float32Array(st, (2 * 21 * NL + 2 * 3 * NL) * 4, 2 * 21 * NL);
const dmax = new Float32Array(st, (2 * 21 * NL + 2 * 3 * NL + 2 * 21 * NL) * 4, 2 * 101);
for (let m = 0; m < 2; m++) {
  let allMono = true, sumOK = true, areaMono = true;
  for (let a = 0; a < 21; a++) for (let c = 1; c < NL; c++) if (bld[(m * 21 + a) * NL + c] < bld[(m * 21 + a) * NL + c - 1]) allMono = false;
  for (let c = 0; c < NL; c += 7) { let s = 0; for (let a = 1; a <= 20; a++) s += bld[(m * 21 + a) * NL + c]; if (s !== bld[(m * 21) * NL + c]) sumOK = false; }
  for (let k = 0; k < 3; k++) for (let c = 1; c < NL; c++) if (area[(m * 3 + k) * NL + c] < area[(m * 3 + k) * NL + c - 1] - 1e-4) areaMono = false;
  ok(allMono, `mode ${m}: building counts non-decreasing`); ok(sumOK, `mode ${m}: arrondissements sum to the total`); ok(areaMono, `mode ${m}: flooded area non-decreasing`);
  let dm = true; for (let k = 1; k < 101; k++) if (dmax[m * 101 + k] < dmax[m * 101 + k - 1] - 1e-4) dm = false; ok(dm, `mode ${m}: max depth non-decreasing`);
  const at_ = (L) => area[(m * 3) * NL + Math.round(L * 100)];
  const b_ = (L) => bld[(m * 21) * NL + Math.round(L * 100)];
  console.log(`mode ${m}: area ha @2018 ${at_(5.84).toFixed(0)}  @2016 ${at_(6.10).toFixed(0)}  @1955 ${at_(7.12).toFixed(0)}  @1910 ${at_(8.62).toFixed(0)}  @10m ${at_(10).toFixed(0)} | buildings @1910 ${b_(8.62)}`);
  ok(at_(5.84) < at_(6.10) && at_(6.10) < at_(7.12) && at_(7.12) < at_(8.62), `mode ${m}: historic floods ordered by area`);
  ok(at_(8.62) > 800 && at_(8.62) < 1500, `mode ${m}: 1910 flooded area plausible (PPRI zones cover ${meta.counts.pprIHa} ha)`);
  ok(at_(0) === 0 && b_(0) === 0, `mode ${m}: nothing flooded at the normal level`);
  ok(b_(10) < n * 0.4, `mode ${m}: building share at +10 m plausible`);
}

// ---- agreement with the regulatory zones at the 1910 level (connected mode)
let inter = 0, uni = 0, ppriN = 0;
for (let i = 0; i < w * h; i++) {
  if (masks[i * 4 + 3] < 128 || T[i] < 0) continue;            // outside Paris / river channel
  const fl = T[i] <= 862, pp = pa[i * 4] > 127 || pa[i * 4 + 1] > 127 || pa[i * 4 + 2] > 127 || pa[i * 4 + 3] > 127 || pb[i * 2] > 127 || pb[i * 2 + 1] > 127;
  if (fl && pp) inter++; if (fl || pp) uni++; if (pp) ppriN++;
}
console.log(`1910 flood vs PPRI zones: IoU ${(inter / uni).toFixed(3)}, share of PPRI area reached ${(inter / ppriN).toFixed(3)}`);
ok(inter / uni > 0.40, 'IoU with PPRI >= 0.40'); ok(inter / ppriN > 0.45, 'at least 45% of the PPRI area is flooded in the model at +8.62 m');

// ---- stations
ok(stations.length === meta.counts.stations, 'station count'); ok(stations.every((s) => s.name && Number.isFinite(s.ngf) && s.ngf > 20 && s.ngf < 135), 'stations have names and a plausible altitude');
const names = new Set(stations.map((s) => s.name)); ok(names.has("Gare d'Austerlitz") || [...names].some((x) => /Austerlitz/.test(x)), 'Austerlitz station present');
const fl1910 = stations.filter((s) => s.tc <= 862).length; console.log(`stations flooded at +8.62 m: ${fl1910} / ${stations.length}`);
ok(fl1910 > 10 && fl1910 < 120, 'flooded stations plausible');
ok(stations.filter((s) => s.tc <= 0).length === 0, 'no station below the gauge zero');
console.log(failed ? `\n${failed} FAILED, ${passed} passed` : `\nall ${passed} checks passed`);
process.exit(failed ? 1 : 0);
EOF
